import{z as A,x as o,o as s,c as d,q as n,j as i,D as l,d as e,s as r,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"代码 RL 与 SWE 环境","description":"","frontmatter":{"title":"代码 RL 与 SWE 环境","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/swe-rl-env.md","filePath":"llm/swe-rl-env.md","lastUpdated":1791413859000}'),p={name:"llm/swe-rl-env.md"};function m(h,a,D,u,R,f){const t=o("Mermaid");return s(),d("div",null,[a[2]||(a[2]=n('<h1 id="代码-rl-与-swe-环境" tabindex="-1">代码 RL 与 SWE 环境 <a class="header-anchor" href="#代码-rl-与-swe-环境" aria-label="Permalink to &quot;代码 RL 与 SWE 环境&quot;">​</a></h1><div class="epigraph"><p>单元测试是单文件的 $R$；修仓库要把终端、测试套件和补丁差分当成环境状态。</p><footer>—— Jimenez 等 SWE-bench；单测验证器课的延伸；开源 SWE-RL / 代理环境</footer></div><p><a href="/llm/multimodal-rlhf">上一课</a>强调奖励必须看见环境。软件工程的环境不是图，是仓库。缺口是：<a href="/llm/code-verifier-unittests">代码单测课</a> 的 HumanEval 式 \\(R\\) 不够——<strong>失败测试在另一文件，动作是补丁与命令。</strong> SWE-bench 把真实 GitHub issue 变成可跑的测试。本课写这套 RL 环境，不重写 GRPO。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单文件函数生成：状态短，动作是一次完成，R 是通过率。仓库级：状态是文件树 + 测试输出，动作是多轮编辑与 shell，地平线长，部分可观测。奖励稀疏：直到测试套件绿。<span class="marginnote">直觉类比：单文件单测像课堂小测验，题目和答题纸都在一页上；仓库级修 bug 像被关进一间堆满档案的办公室，门上贴着一张报修单，修没修好由门外的验收员（测试套件）说了算——而且验收标准一份都不许动。环境从「答题」变成了「搜证 + 动手 + 过验收」。</span>黑客：改测试、删断言、硬编码期望。环境必须锁测试只读、网络关、超时。Jimenez 等的评测协议已经在防这些；训练环境若更松，RL 会学评测里禁止的动作。</p><p>代理框架（工具循环）与 RL 的关系：环境步进由工具执行，策略只产 token（命令 / 补丁）。与 <a href="/llm/ppo-llm">PPO</a> 接口相同，轨迹更长，GAE \\(\\lambda\\) 要大，过长过滤要按「是否还在跑测试」标记。</p><h3 id="评测集污染" tabindex="-1">评测集污染 <a class="header-anchor" href="#评测集污染" aria-label="Permalink to &quot;评测集污染&quot;">​</a></h3><p>SWE-bench 的 issue 可能进过预训练。RL 再在同一仓库上刷，分数不可信。应锁训练仓库与评测仓库分离，像隐藏测例。</p><p><span class="marginnote">「用 GPT-4 评代码是否优雅」不是本课 \\(R\\)。本课只认测试与格式化检查器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>环境：检出仓库、应用补丁、跑指定测试命令，返回日志与 \\(R\\in\\{0,1\\}\\) 或失败测例比例。策略：多轮，每轮可调工具。训练：GRPO / PPO，组内多条补丁轨迹。过程信号：编译过、单测从 3 fail 到 1 fail 给稠密塑形，注意不要奖励「删测试」。基线：SWE-bench 官方脚手架；RL 论文应声明是否改环境规则。</p>',11)),(s(),i(B,null,{default:l(()=>[r(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISS%5B%22issue%20%2B%20%E4%BB%93%E5%BA%93%22%5D%20--%3E%20ACT%5B%22%E7%BC%96%E8%BE%91%20%2F%20%E5%91%BD%E4%BB%A4%20token%22%5D%0A%20%20ACT%20--%3E%20ENV%5B%22%E6%B2%99%E7%AE%B1%EF%BC%9A%E8%A1%A5%E4%B8%81%20%2B%20pytest%22%5D%0A%20%20ENV%20--%3E%20LOG%5B%22%E6%97%A5%E5%BF%97%22%5D%0A%20%20LOG%20--%3E%20R%5B%22%E6%B5%8B%E8%AF%95%E5%A5%96%E5%8A%B1%22%5D%0A%20%20R%20--%3E%20RL%5B%22PPO%20%2F%20GRPO%22%5D%0A%20%20ENV%20--%3E%20BAN%5B%22%E7%A6%81%E6%AD%A2%E6%94%B9%E6%B5%8B%E8%AF%95%20%2F%20%E5%87%BA%E7%BD%91%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与工具整合课衔接：本课环境以测试为终局；下一课把计算器、检索当中途工具，终局仍可能是数学对错。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("长地平线 + 稀疏 \\(R\\) 使随机探索几乎不可能碰巧修对。需要 SFT 冷启动（示范轨迹）再 RL，类似 R1 的冷启动。"),E("span",{class:"marginnote"},"「SFT 冷启动」翻译一下：先用人类示范轨迹教模型「扳手怎么拿」——搜文件、看日志、按行改、跑测试；再让 RL 在这个会用的基础上练「修得更快更准」。跳过冷启动直接 RL，等于让没摸过工具的人随机乱敲，奖励又是 0/1，几乎永远敲不绿，梯度里全是噪声。"),e("RL 负责在已会用工具的策略上提高通过率。过优化环境洞：只过公开 fail2pass，不过 hidden。金标必须含 hidden tests，与单测课同一原则。")],-1)),(s(),i(B,null,{default:l(()=>[r(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20HACK%5B%22%E6%99%BA%E8%83%BD%E4%BD%93%E5%8F%AF%E8%83%BD%E7%9A%84%E4%BD%9C%E5%BC%8A%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20H1%5B%22%E6%94%B9%E6%B5%8B%E8%AF%95%20%E5%88%A0%E6%96%AD%E8%A8%80%22%5D%0A%20%20HACK%20--%3E%20H2%5B%22%E7%A1%AC%E7%BC%96%E7%A0%81%E6%9C%9F%E6%9C%9B%E8%BE%93%E5%87%BA%22%5D%0A%20%20HACK%20--%3E%20H3%5B%22%E8%81%94%E7%BD%91%E6%8A%84%E7%8E%B0%E6%88%90%E8%A1%A5%E4%B8%81%22%5D%0A%20%20HACK%20--%3E%20H4%5B%22%E5%8F%8D%E5%A4%8D%E5%88%B7%E8%AE%AD%E7%BB%83%E9%87%8C%E8%A7%81%E8%BF%87%E7%9A%84%E9%A2%98%22%5D%0A%20%20H1%20--%3E%20G1%5B%22%E9%97%B8%201%20%E6%B5%8B%E8%AF%95%E6%96%87%E4%BB%B6%E5%8F%AA%E8%AF%BB%22%5D%0A%20%20H2%20--%3E%20G2%5B%22%E9%97%B8%202%20%E5%8F%AA%E8%AE%A4%20hidden%20tests%22%5D%0A%20%20H3%20--%3E%20G3%5B%22%E9%97%B8%203%20%E6%B2%99%E7%AE%B1%E6%96%AD%E7%BD%91%22%5D%0A%20%20H4%20--%3E%20G4%5B%22%E9%97%B8%204%20%E8%AE%AD%E7%BB%83%E4%B8%8E%E8%AF%84%E6%B5%8B%E4%BB%93%E5%BA%93%E5%88%86%E7%A6%BB%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：把「失败测试从 3 个降到 1 个」自动当成进步来奖励。数字接近不等于方向正确——删掉一个测试文件同样能让 3 变 1，却是纯作弊。过程塑形奖励的必须是「编译通过」「新增失败减少」这类不可被删除行为伪造的信号。</span></p><p><span class="marginnote">墙钟由测试套件主导。batch 按仓库分组，避免短测等长测。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有可跑测试的 issue 不属于本课，退回裁判。前端视觉回归接近多模态。下一课工具整合推理：数学/代码混合工具，环境更轻，但「工具结果必须进 \\(R\\) 的定义」同一条。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SWE-RL 的状态是仓库与终端，奖励是锁死的测试套件，不是单文件单测。</li><li>防黑客：测试只读、无网、hidden tests、训练评测仓库分离。</li><li>需要示范冷启动；纯随机补丁不会绿。</li><li>过程塑形勿奖励删测试。</li><li>出处：Jimenez 等 SWE-bench；HumanEval / CodeRL 为单文件对照；R1 代码奖励为规则 \\(R\\)。</li></ul>',6))])}const S=A(p,[["render",m]]);export{b as __pageData,S as default};
